#!/usr/bin/env bash
set -euo pipefail
ROOT="TVRemote"
rm -rf "$ROOT"
mkdir -p "$ROOT"
cat > /tmp/tvremote_payload.b64 <<'PAYLOAD'

PAYLOAD
base64 -d /tmp/tvremote_payload.b64 > /tmp/tvremote_payload.zip
python3 - <<'PY'
import zipfile
with zipfile.ZipFile("/tmp/tvremote_payload.zip") as z:
    z.extractall("TVRemote")
print("TVRemote v2.1 project created successfully.")
PY
rm -f /tmp/tvremote_payload.b64 /tmp/tvremote_payload.zip
echo "Commit the TVRemote folder, then open Actions -> Build TV Remote APKs -> Run workflow."
